// Database row types for the Song Library service (migration 419).
//
// Kept apart from src/lib/departments/db.types.ts: the Song Library is a
// base-wide Hub Service, not a department table. src/types/database.ts is
// generated by `supabase gen types` and must not be edited by hand; import
// these shapes until that file includes the song_library_* tables.
//
// Timestamps are ISO strings (timestamptz). numeric columns (split_pct,
// duration_s) come back from PostgREST as numbers.

export const SONG_LIBRARY_SERVICE_KEY = "song_library" as const;
export const SONG_LIBRARY_BUCKET = "song-library" as const;

/** Stages in board order. Finished = demo_ready or later. */
export const SONG_STAGES = [
  "idea_entry",
  "writing",
  "set_down",
  "refine",
  "written_needs_demo",
  "demo_ready",
  "share",
  "celebrate",
] as const;
export type SongStage = (typeof SONG_STAGES)[number];
export const FINISHED_STAGES = [
  "demo_ready",
  "share",
  "celebrate",
] as const satisfies readonly SongStage[];

/** personal = Personal (Devo/Balladeers). */
export const SONG_PLACEMENTS = [
  "inbox",
  "prayer_sets",
  "ministry_nights",
  "events",
  "ffsa_music",
  "personal",
] as const;
export type SongPlacement = (typeof SONG_PLACEMENTS)[number];

export const SONG_ENTRY_POINTS = ["lyric", "melody", "instrumental"] as const;
export type SongEntryPoint = (typeof SONG_ENTRY_POINTS)[number];
/** Also the pathway step names. */
export type SongPathwayStep = SongEntryPoint;

/**
 * b1 = the two steps after entry_point in lyric, melody, instrumental
 * order; b2 = reversed. Melody entry: b1 = lyric then instrumental.
 */
export const SONG_PATHWAYS = ["b1", "b2"] as const;
export type SongPathway = (typeof SONG_PATHWAYS)[number];

export const SONG_EVENT_KINDS = [
  "stage",
  "placement",
  "checkpoint",
  "version",
  "writer",
] as const;
export type SongEventKind = (typeof SONG_EVENT_KINDS)[number];

export const SONG_SHARE_KINDS = [
  "close_friend",
  "group_open_mic",
  "social",
  "congregation",
  "record_release",
] as const;
export type SongShareKind = (typeof SONG_SHARE_KINDS)[number];

export const SONG_CHECKPOINT_KINDS = [
  "credits_splits_agreed",
  "prayer_room_test",
  "ministry_night_debut",
  "event",
  "recording",
] as const;
export type SongCheckpointKind = (typeof SONG_CHECKPOINT_KINDS)[number];

export const SONG_HELP_CATEGORIES = [
  "vocals",
  "keys",
  "guitar",
  "bass",
  "drums",
  "demo_production",
  "lyric_feedback",
  "charts",
] as const;
export type SongHelpCategory = (typeof SONG_HELP_CATEGORIES)[number];

export const SONG_HELP_STATUSES = ["open", "filled", "closed"] as const;
export type SongHelpStatus = (typeof SONG_HELP_STATUSES)[number];

export const SONG_SUBSCRIPTION_TARGETS = ["all_uploads", "writer"] as const;
export type SongSubscriptionTarget = (typeof SONG_SUBSCRIPTION_TARGETS)[number];

export const SONG_NOTIFICATION_KINDS = [
  "new_upload",
  "stage_moved",
  "help_asked",
] as const;
export type SongNotificationKind = (typeof SONG_NOTIFICATION_KINDS)[number];
export const SONG_NOTIFICATION_REASONS = [
  "all_uploads",
  "writer",
  "helper_category",
] as const;
export type SongNotificationReason = (typeof SONG_NOTIFICATION_REASONS)[number];

/** Refine: 1–10 are the handbook questions (text in code), 11 is the bonus. */
export const REFINE_BONUS_Q_NO = 11 as const;

/**
 * Writers may move a song only between these stages; moves into or out of
 * demo_ready, share or celebrate are managers' (trigger-enforced).
 */
export const SONG_EARLY_STAGES = [
  "idea_entry",
  "writing",
  "set_down",
  "refine",
  "written_needs_demo",
] as const satisfies readonly SongStage[];

/**
 * song_library_songs. placement: managers only. stage: managers make any
 * move, writers early moves only (SONG_EARLY_STAGES). Every move is logged
 * with who made it.
 */
export interface SongLibrarySong {
  id: string;
  title: string;
  /** Set to the uploader by trigger. */
  created_by: string | null;
  entry_point: SongEntryPoint;
  pathway: SongPathway | null;
  holy_spirit_interrupt: boolean;
  stage: SongStage;
  placement: SongPlacement;
  music_key: string | null;
  bpm: number | null;
  lyrics_md: string | null;
  /** Object name in the song-library bucket, `{song_id}/...`. */
  chart_path: string | null;
  /** Must be a version of this song. Set to the first upload automatically. */
  current_version_id: string | null;
  /** Always 'base' (visible to the whole base). */
  visibility: "base";
  /** pw_songwriting_trainings.id (417). No FK yet. */
  source_training_id: string | null;
  /** Trigger-maintained; drives stuck. */
  last_activity_at: string;
  created_at: string;
  updated_at: string;
}

/** Columns a client may send when uploading. The rest are defaulted or forced. */
export type SongLibrarySongInsert = Pick<
  SongLibrarySong,
  "title" | "entry_point"
> &
  Partial<
    Pick<
      SongLibrarySong,
      | "pathway"
      | "holy_spirit_interrupt"
      | "music_key"
      | "bpm"
      | "lyrics_md"
      | "chart_path"
      | "source_training_id"
    >
  > & {
    /** Honoured only for managers and admins; otherwise forced to idea_entry / inbox. */
    stage?: SongStage;
    placement?: SongPlacement;
  };

/** song_library_versions. n is assigned per song by trigger. */
export interface SongLibraryVersion {
  id: string;
  song_id: string;
  n: number;
  label: string | null;
  /** `{song_id}/...` in the song-library bucket. Unique. */
  storage_path: string;
  mime_type: string | null;
  size_bytes: number | null;
  duration_s: number | null;
  is_demo: boolean;
  /** 12 chars, no hyphens: /^[A-Z]{2}[A-Z0-9]{3}[0-9]{7}$/ */
  isrc: string | null;
  uploaded_by: string | null;
  uploaded_at: string;
  updated_at: string;
}

/** song_library_pathway_steps. A row = step done. */
export interface SongLibraryPathwayStep {
  song_id: string;
  step: SongPathwayStep;
  done_at: string;
  by_user: string | null;
}

/** song_library_stage_events ("Where it's been"). Written by triggers only. */
export interface SongLibraryStageEvent {
  id: string;
  song_id: string;
  kind: SongEventKind;
  /** Set only for kind 'stage'. from_stage is null on the creation event. */
  from_stage: SongStage | null;
  to_stage: SongStage | null;
  /**
   * stage (creation): { created: true, entry_point, holy_spirit_interrupt }
   * placement: { from, to }
   * checkpoint: { checkpoint, done, note }, plus { revoked: true, deleted,
   *   cleared_confirmations } when a ticked credits_splits_agreed is
   *   unticked or deleted (by_user = who revoked; null = service role)
   * version: { version_id, n, label, is_demo }
   * writer: { action: 'added' | 'removed', writer_id, user_id, display_name, is_lead }
   *   | { action: 'confirmed', writer_id, user_id, display_name, split_pct }
   *   | { action: 'unconfirmed', writer_id, user_id, display_name }
   *   | { action: 'confirmations_cleared', writer_id, cleared_confirmations }
   */
  payload: Record<string, unknown>;
  by_user: string | null;
  at: string;
  /** The only column a user may edit, and only on their own event. */
  note: string | null;
}

/** song_library_refine_items. by_user/at stamped on write. */
export interface SongLibraryRefineItem {
  song_id: string;
  /** 1–10 handbook questions, 11 = bonus. */
  q_no: number;
  checked: boolean;
  note: string | null;
  by_user: string | null;
  at: string;
}

export interface SongLibraryShareStep {
  song_id: string;
  kind: SongShareKind;
  done_at: string;
  by_user: string | null;
}

/**
 * Read only by the song's writers and co-writers, Song Library managers
 * (manage grant: P&W members) and admins. Written by the song's writers
 * (and admins).
 */
export interface SongLibraryCelebrateNote {
  song_id: string;
  /** 1–5 */
  prompt_no: number;
  body: string;
  by_user: string | null;
  created_at: string;
  updated_at: string;
}

/**
 * song_library_writers. One is_lead per song (the uploader by default).
 * user_id null = no Hub account; display_name is then required.
 *
 * Per-writer sign-off: an account writer confirms only their own row
 * (send any non-null confirmed_at; the Hub stamps now() and
 * confirmed_by). A no-account row is confirmed by a manager or admin.
 * Agreed = splits total 100.00 and every row confirmed.
 *
 * Credit fields: user_id, display_name, role, is_lead, split_pct, plus
 * adding/removing a row. Not agreed: a credit change clears every
 * confirmation. Agreed: credit changes are refused (23514) until the
 * agreement is revoked, by un-confirming a row (that writer, a manager or
 * an admin) or a manager/admin unticking/deleting the checkpoint.
 * Revoking clears every confirmation and is logged.
 */
export interface SongLibraryWriter {
  id: string;
  song_id: string;
  user_id: string | null;
  display_name: string | null;
  role: string | null;
  is_lead: boolean;
  /** 0–100, two decimals. */
  split_pct: number | null;
  /** Set by the Hub when confirmed; null = not confirmed. */
  confirmed_at: string | null;
  /** Who confirmed (the writer, or a manager/admin for no-account rows). */
  confirmed_by: string | null;
  added_by: string | null;
  created_at: string;
  updated_at: string;
}

/** One PRO entry, keyed by song_library_writers.id in pro_by_writer. */
export interface SongLibraryProEntry {
  pro?: string | null;
  member_no?: string | null;
}

/**
 * song_library_publishing. One row per song. ISRC is per version.
 * Edited by the song's writers, managers and admins.
 */
export interface SongLibraryPublishing {
  song_id: string;
  /** Digits only, up to 10. */
  ccli_no: string | null;
  publisher: string | null;
  pro_by_writer: Record<string, SongLibraryProEntry>;
  notes: string | null;
  updated_by: string | null;
  created_at: string;
  updated_at: string;
}

/**
 * Ticked = done_at not null. Managers (and admins) tick every kind except
 * credits_splits_agreed, which is derived from the writers' confirmations
 * (nobody ticks it by hand). Managers may untick or delete it to revoke.
 */
export interface SongLibraryCheckpoint {
  song_id: string;
  kind: SongCheckpointKind;
  done_at: string | null;
  by_user: string | null;
  note: string | null;
  created_at: string;
  updated_at: string;
}

/** song_library_helpers. Helper profile, one row per category. */
export interface SongLibraryHelper {
  user_id: string;
  category: SongHelpCategory;
  note: string | null;
  created_at: string;
}

/** song_library_help_requests. asked_by forced to the caller. */
export interface SongLibraryHelpRequest {
  id: string;
  song_id: string;
  asked_by: string | null;
  categories: SongHelpCategory[];
  body: string;
  status: SongHelpStatus;
  helper_user_id: string | null;
  /** Null exactly while status is 'open'. Trigger-maintained. */
  closed_at: string | null;
  created_at: string;
  updated_at: string;
}

/** song_library_help_signups ("I can help"). Only on open requests. */
export interface SongLibraryHelpSignup {
  id: string;
  request_id: string;
  user_id: string;
  note: string | null;
  created_at: string;
  updated_at: string;
}

/** song_library_subscriptions. Own rows only. */
export interface SongLibrarySubscription {
  id: string;
  user_id: string;
  target_type: SongSubscriptionTarget;
  /** Set exactly when target_type is 'writer'. Never the subscriber. */
  target_user_id: string | null;
  created_at: string;
}

/**
 * song_library_notifications. DM outbox / idempotency claim, service role
 * writes. Unique per (user_id, song_id) for new_upload, (user_id,
 * stage_event_id) for stage_moved, (user_id, help_request_id) for help_asked.
 */
export interface SongLibraryNotification {
  id: string;
  user_id: string;
  song_id: string;
  kind: SongNotificationKind;
  stage_event_id: string | null;
  help_request_id: string | null;
  reason: SongNotificationReason;
  slack_ts: string | null;
  sent_at: string | null;
  created_at: string;
}

/** song_library_stage_settings. Eight fixed rows. Null = never stuck. */
export interface SongLibraryStageSetting {
  stage: SongStage;
  stuck_after_days: number | null;
  updated_by: string | null;
  updated_at: string;
}

/** song_library_song_status view (security_invoker). */
export interface SongLibrarySongStatus {
  song_id: string;
  stage: SongStage;
  placement: SongPlacement;
  last_activity_at: string;
  stuck_days: number;
  stuck_after_days: number | null;
  is_stuck: boolean;
  is_finished: boolean;
  needs_demo: boolean;
  /** Splits total 100.00 and every writer has confirmed. */
  splits_agreed: boolean;
  /** Sum of split_pct (0 when no splits). */
  splits_total_pct: number;
  writers_count: number;
  writers_confirmed: number;
}
